 static JSONObject known()throws Exception{JSONObject c=SectorLeaderModel.normalize(legacy());c.getJSONArray("sectors").getJSONObject(0).getJSONArray("leaders").getJSONObject(0).put("fullId","SH:stock:601939").put("identityState","confirmed-user");return c;}
