 static void onUi(Work action)throws Exception{if(Looper.myLooper()==Looper.getMainLooper()){action.run();return;}CountDownLatch done=new CountDownLatch(1);AtomicReference<Throwable> error=new AtomicReference<>();new Handler(Looper.getMainLooper()).post(()->{try{action.run();}catch(Throwable e){error.set(e);}finally{done.countDown();}});need(done.await(5,TimeUnit.SECONDS),"UI bounded callback");if(error.get()!=null)throw new AssertionError(error.get());}
