   onUi(()->{SectorLeaderScreen p=screen[0];p.discard();p.setDarkTheme(true);p.showPane(4);p.measure(View.MeasureSpec.makeMeasureSpec(p.dp(760),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(p.dp(240),View.MeasureSpec.EXACTLY));p.layout(0,0,p.dp(760),p.dp(240));need(p.getOrientation()==LinearLayout.HORIZONTAL&&p.chart.getHeight()>=p.dp(40),"landscape chart visible with scrollable detail");p.setActive(false);need(!p.busy&&!p.chart.active,"hidden page cancels work");});
